// MARK: - VideoAnalysis (video_analyses)

/// Machine analysis of one submission version: transcript, scenes, beats, hook, QA checks and checklist scores. One row per (submission, version).
struct VideoAnalysis: Codable, Hashable, Identifiable, Sendable {
    /// va_<submission number>_v<version>.
    var id: String
    var submissionId: String
    var version: Int
    var durationMs: Int
    var language: String
    var transcript: [TranscriptSegment]
    /// The segments joined with spaces.
    var transcriptText: String
    var onScreenText: [OnScreenText]
    var scenes: [SceneCut]
    var hook: HookAnalysis
    var beats: [BeatHit]
    var tags: VideoTags
    /// One entry per QaCheckType that ran.
    var checks: [QaCheck]
    /// Hook Score checklist (weights sum to 100).
    var hookScore: ScoreCard
    /// Flow Score checklist (weights sum to 100).
    var flowScore: ScoreCard
    /// 16 hex chars: perceptual hash for duplicate detection.
    var phash: String
    var duplicateOfSubmissionId: String?
    var analysedAt: Date
}

// MARK: - FeedbackNote (feedback_notes)

/// A timecoded feedback note on a submission version: anchored to a moment in the video, with a category and a severity. Must-fix notes carry over to the next version until the creator ticks them off. Qa_checks live inside video_analyses.checks.
struct FeedbackNote: Codable, Hashable, Identifiable, Sendable {
    var id: String
    var submissionId: String
    var bountyId: String
