    /// End of a range, when the note covers a span.
    var tEndMs: Int?
    var category: FeedbackCategory
    var severity: FeedbackSeverity
    var status: FeedbackStatus
    /// About the video, never the person.
    var body: String
    /// Set when the note supports a request-changes or reject decision.
    var reasonCode: ReasonCode?
    var resolvedInVersion: Int?
    var resolvedAt: Date?
    var createdAt: Date
}

